package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ResponseTypesJsonVO;

class ResponseTypesJsonValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of response types json of oauth client")
  void test_response_types_json_value_holder_assign_plain_value() {
    Object holder = new Object();
    ResponseTypesJsonValueHolder<Object> value = new ResponseTypesJsonValueHolder<>(holder);
    Assertions.assertSame(holder, value.responseTypesJson("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getResponseTypesJsonValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getResponseTypesJson().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.responseTypesJsonNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getResponseTypesJsonValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getResponseTypesJson().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of response types json of oauth client")
  void test_response_types_json_value_holder_assign_value_object() {
    Object holder = new Object();
    ResponseTypesJsonValueHolder<Object> value = new ResponseTypesJsonValueHolder<>(holder);
    ResponseTypesJsonVO vo = ResponseTypesJsonVO.from("one");
    Assertions.assertFalse(value.getResponseTypesJsonValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.responseTypesJson(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getResponseTypesJsonValue().orElseThrow());
    Assertions.assertSame(holder, value.responseTypesJson(Optional.empty()));
    Assertions.assertFalse(value.getResponseTypesJsonValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.responseTypesJson(Optional.of(vo)));
    Assertions.assertSame(vo, value.getResponseTypesJsonValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of response types json of oauth client against the original")
  void test_response_types_json_value_holder_read() {
    Object holder = new Object();
    ResponseTypesJsonValueHolder<Object> value = new ResponseTypesJsonValueHolder<>(holder);
    ResponseTypesJsonVO vo = ResponseTypesJsonVO.from("one");
    ResponseTypesJsonVO other = ResponseTypesJsonVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getResponseTypesJsonValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readResponseTypesJson(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readResponseTypesJson(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.responseTypesJson(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readResponseTypesJson(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readResponseTypesJson(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of response types json of oauth client")
  void test_response_types_json_value_holder_unset() {
    Object holder = new Object();
    ResponseTypesJsonValueHolder<Object> value = new ResponseTypesJsonValueHolder<>(holder);
    ResponseTypesJsonVO vo = ResponseTypesJsonVO.from("one");
    value.responseTypesJson(vo);
    Assertions.assertSame(holder, value.unsetResponseTypesJsonIfMatches("responseTypesJson_other"));
    Assertions.assertTrue(value.getResponseTypesJsonValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetResponseTypesJsonIfMatches("responseTypesJson"));
    Assertions.assertFalse(value.getResponseTypesJsonValue().isPresent(),
        "The field name must clear the value");
    value.responseTypesJson(vo);
    Assertions.assertSame(holder, value.unsetResponseTypesJson());
    Assertions.assertFalse(value.getResponseTypesJsonValue().isPresent(),
        "Unset must clear the value");
  }
}
